def parse_duration(s: str) -> int:
    if not s or not isinstance(s, str):
        raise ValueError(f"Invalid duration string: {s!r}")

    total_seconds = 0
    i = 0
    n = len(s)

    while i < n:
        # Read the number
        start = i
        while i < n and s[i].isdigit():
            i += 1
        if i == start:
            raise ValueError(f"Invalid duration string: {s!r}")
        number = int(s[start:i])

        # Read the unit
        if i >= n:
            raise ValueError(f"Missing unit in duration string: {s!r}")
        unit = s[i]
        i += 1

        if unit == 'h':
            total_seconds += number * 3600
        elif unit == 'm':
            total_seconds += number * 60
        elif unit == 's':
            total_seconds += number
        else:
            raise ValueError(f"Unknown unit '{unit}' in duration string: {s!r}")

    if i != n:
        raise ValueError(f"Trailing characters in duration string: {s!r}")

    return total_seconds
